import { SpotLight } from '@orillusion/core';

// The wall switch of the laundromat: clicking it (or pressing L) turns the
// ceiling fluorescents off and on, with the light they throw on the ceiling.
// With them off the room falls back on the neon, the vending machine, the
// heater and the street lamp coming through the glass.
export default class FluorescentSwitch extends Script {
    brightness = 1;     // the fixtures' brightness while on, times each one's own
    fade = 3;           // how quickly they come up and go down
    count = 9;          // how many ceiling fixtures the switch controls
    bounces = 2;        // lights standing for the fixtures' light off the ceiling
    tubeGlow = 3;       // how bright the tubes glow while on

    start() {
        this.on = true;
        // Each light fades to the brightness the scene gives it.
        this.lights = [];
        const add = (name) => {
            const obj = this.find(name);
            const comp = obj && obj.getComponent ? obj.getComponent(SpotLight) : null;
            if (comp && typeof comp.intensity === 'number') this.lights.push({ comp, full: comp.intensity });
        };
        this.tubeNames = [];
        for (let i = 1; i <= this.count; i++) {
            add('Fluorescent Light ' + i);
            this.tubeNames.push('Fluorescent Tube ' + i);
        }
        for (let i = 1; i <= this.bounces; i++) add('Ceiling Bounce ' + i);
        this.glow(this.on);
    }

    glow(on) {
        for (const name of this.tubeNames) {
            const obj = this.find(name);
            if (obj) this.setEmissive(on ? '#eaf6ff' : '#151b21', on ? this.tubeGlow : 0, obj);
        }
    }

    toggle() {
        this.on = !this.on;
        this.glow(this.on);
        this.playSound('switch', { volume: 0.5, at: this.object3D });
        this.log('fluorescent lights', this.on ? 'on' : 'off');
    }

    update(dt) {
        const k = Math.min(1, dt * this.fade);
        for (const light of this.lights) {
            const target = this.on ? light.full * this.brightness : 0;
            light.comp.intensity += (target - light.comp.intensity) * k;
        }
    }

    onPointerDown() { this.toggle(); }
    onKeyDown(key) { if (key === 'l') this.toggle(); }
}

// The laundromat's automatic sliding door: its two glass leaves part when
// someone comes near and close again a moment after they have gone. The
// scene keeps the door open, so the level check and the editor's walk go
// through it; Play starts it closed. The leaves are solid while closed, so
// they open early enough for a running player. The sensor lights over the
// door turn green while it opens for someone.
export default class AutoDoor extends Script {
    range = 2.6;        // meters from the door at which it opens
    travel = 0.9;       // how far each leaf slides, meters
    speed = 2.2;        // how fast the leaves slide, meters per second
    hold = 1.5;         // seconds it stays open after the last one has gone
    others = 'Cat';     // more objects it opens for, by name (comma separated)

    start() {
        this.left = this.find('Door Leaf L');
        this.right = this.find('Door Leaf R');
        // Where the scene keeps the leaves: open.
        this.openLeft = this.left ? this.left.x : 0;
        this.openRight = this.right ? this.right.x : 0;
        this.walkers = ['Player', ...this.others.split(',')].map((name) => name.trim()).filter(Boolean);
        this.lights = this.findAll('Door Sensor Light');
        this.amount = 0;
        this.timer = 0;
        this.place();
    }

    // Whether anyone it opens for is within range of the door, on the ground plane.
    someoneNear() {
        const door = this.object3D.transform.worldPosition;
        const x = door.x, z = door.z;
        for (const name of this.walkers) {
            for (const obj of this.findAll(name)) {
                const p = obj.transform.worldPosition;
                if (Math.hypot(p.x - x, p.z - z) < this.range) return true;
            }
        }
        return false;
    }

    update(dt) {
        const near = this.someoneNear();
        if (near) this.timer = this.hold;
        else this.timer -= dt;
        if (near !== this.near) {
            this.near = near;
            for (const light of this.lights) this.setEmissive(near ? '#3dff7a' : '#ff3b30', near ? 3 : 1, light);
        }
        const target = this.timer > 0 ? 1 : 0;
        const step = (this.speed / this.travel) * dt;
        const was = this.amount;
        this.amount += Math.max(-step, Math.min(step, target - this.amount));
        if (this.amount !== was) this.place();
    }

    // Eases the leaves between closed (0) and open (1).
    place() {
        const t = this.amount;
        const k = t * t * (3 - 2 * t);
        if (this.left) this.left.x = this.openLeft + (1 - k) * this.travel;
        if (this.right) this.right.x = this.openRight - (1 - k) * this.travel;
    }
}

// A washing machine or a dryer of the laundromat (on the root of a Washer or
// Dryer prefab copy). Click it in Play to start a cycle once it stands idle
// or is done. The laundry tumbles behind the glass: a washer turns it slowly
// one way, then the other, while it washes, then spins it fast and shakes;
// a dryer turns it one way the whole time with its drum lit warm. The
// display stands by in amber, shows red while it runs and green when done.
export default class Washer extends Script {
    running = false;    // runs from the start of Play
    offset = 0;         // seconds into its cycle it starts at, when running
    cycle = 24;         // seconds of washing or drying
    spin = 8;           // seconds of spinning at the end (washers only)
    turn = 150;         // degrees per second the drum turns while washing or drying
    spinTurn = 900;     // degrees per second at the top of the spin

    start() {
        this.dryer = /dryer/i.test(this.object3D.name);
        const kind = this.dryer ? 'Dryer' : 'Washer';
        this.laundry = this.object3D.getChildByName(kind + ' Laundry');
        this.glass = this.object3D.getChildByName(kind + ' Glass');
        this.display = this.object3D.getChildByName(kind + ' Display');
        this.home = { y: this.object3D.y, z: this.object3D.z };
        this.shaking = false;
        this.t = this.running ? this.offset : -1;
        this.angle = 0;
        this.shown = '';
        this.show();
    }

    // Seconds from start to done.
    cycleLength() {
        return this.cycle + (this.dryer ? 0 : this.spin);
    }

    // What it does now: idle, wash (or dry), spin or done.
    phase() {
        if (this.t < 0) return 'idle';
        if (this.t < this.cycle) return 'wash';
        if (this.t < this.cycleLength()) return 'spin';
        return 'done';
    }

    onClick() {
        const p = this.phase();
        if (p !== 'idle' && p !== 'done') return;
        this.t = 0;
        this.log(this.object3D.name, 'started');
    }

    update(dt) {
        if (this.t >= 0 && this.t < this.cycleLength()) this.t += dt;
        const p = this.phase();
        let speed = 0;
        if (p === 'wash') {
            // A dryer turns one way; a washer turns, rests, turns back, rests.
            const k = this.t % 7;
            speed = this.dryer ? this.turn : k < 3 ? this.turn : k < 3.5 ? 0 : k < 6.5 ? -this.turn : 0;
        } else if (p === 'spin') {
            // Up to full speed over two seconds, down over the last one.
            const into = this.t - this.cycle;
            const left = this.cycleLength() - this.t;
            speed = this.spinTurn * Math.min(1, into / 2, left);
        }
        this.angle = (this.angle + speed * dt) % 360;
        if (this.laundry) this.laundry.rotationX = this.angle;
        // The fast spin shakes the machine a little.
        const shake = p === 'spin' ? 0.0025 * Math.min(1, Math.abs(speed) / this.spinTurn) : 0;
        if (shake > 0) {
            const s = this.time.elapsed;
            this.object3D.y = this.home.y + shake * Math.sin(s * 97);
            this.object3D.z = this.home.z + shake * Math.sin(s * 71 + 1);
            this.shaking = true;
        } else if (this.shaking) {
            this.object3D.y = this.home.y;
            this.object3D.z = this.home.z;
            this.shaking = false;
        }
        if (p !== this.shown) this.show();
    }

    // The display, and a dryer's lit drum.
    show() {
        const p = this.phase();
        this.shown = p;
        if (this.display) {
            if (p === 'idle') this.setEmissive('#ff8a2a', 0.6, this.display);
            else if (p === 'done') this.setEmissive('#3bff6a', 2.2, this.display);
            else this.setEmissive('#ff3b30', 2.2, this.display);
        }
        if (this.dryer && this.glass) this.setEmissive('#ff9a52', p === 'wash' ? 0.35 : 0, this.glass);
    }
}

import { Color, MeshRenderer, PointLight, SpotLight } from '@orillusion/core';

// The laundromat cat is the OIIA cat: "Oiiaioooooiai Cat" by Zhuier
// (https://sketchfab.com/3d-models/oiiaioooooiai-cat-30d27bf7fb224849b76e208a6eccdb36),
// CC BY 4.0. Its behavior tree (Behavior tab) decides what it does: put a can
// from the vending machine down on the floor and it runs to it, takes it and
// does the OIIA spin while the lights go disco; someone running close by
// sends it under the side bench; it comes over to go round a visitor it
// trusts, watches one who stands still, and otherwise naps by the heater,
// watches a washer turn, looks out at the rain or washes itself on the bench.
// This script writes what it notices into fact keys, carries out the tasks
// the tree names and keeps it lively: it hops along as it walks, breathes as
// it sleeps, crouches to hide and opens its mouth to meow.

// The OIIA spin as the model's own animation has it: the degrees it has
// turned and its bounce (centimeters) every `step` seconds.
const SPIN = {"step":0.06667,"length":4.833,"bob":[0,0.1,0.5,1,1.5,2,2.3,2.4,2.3,2,1.5,0.8,0,-0.9,-1.6,-2.3,-2.8,-3.1,-3.1,-2.5,-1.2,0.6,2.4,4,5.1,5.4,5.1,4.1,2.4,0.5,-1.3,-3,-4,-4.3,-4.1,-3.2,-1.9,-0.4,1,2,2.5,2.5,2,1.1,0.2,-0.6,-1,-1,0.2,2.2,4.1,5.1,5,3.4,0.9,-1.8,-3.7,-4.1,-3.9,-3.2,-2.2,-1.1,0,0.7,1,0.7,0,-0.9,-1.9,-2.7,-3.1,-3.1,-2.8,-2.2,-1.4,-0.7,-0.2,0],"turn":[0,97,195,292,390,487,585,670,731,829,926,1024,1121,1219,1316,1414,1511,1609,1657,1755,1852,1949,2046,2143,2240,2313,2385,2482,2579,2675,2772,2868,2965,3037,3109,3205,3300,3396,3492,3587,3682,3730,3825,3920,4015,4109,4203,4250,4345,4438,4532,4626,4672,4765,4858,4951,5044,5101,5182,5274,5365,5457,5548,5639,5730,5820,5910,6000,6090,6179,6268,6312,6401,6489,6577,6665,6752,6839]};
const BEAT = 0.4;   // seconds between the disco lights' colors
const CONFETTI = ['#ff4f9a', '#ffd23f', '#3ee0ff', '#7cff6b', '#b388ff', '#ff8a3d'];

export default class Cat extends Script {
    discoLights = 9;    // ceiling lights that join the dance

    start() {
        this.player = this.find('Player');
        this.spinner = this.find('Cat Spin');
        this.figure = this.find('Cat Model');
        this.can = this.getScript('Soda Can', 'SodaCan');
        const b = this.figure;
        this.rest = { y: this.spinner ? this.spinner.y : 0, sx: b ? b.scaleX : 1, sy: b ? b.scaleY : 1, sz: b ? b.scaleZ : 1 };
        // The lights that dance with it, and their own colors to go back to.
        this.lights = [];
        for (let i = 1; i <= this.discoLights; i++) {
            const obj = this.find('Fluorescent Light ' + i);
            const comp = obj && obj.getComponent ? obj.getComponent(SpotLight) : null;
            if (comp) this.lights.push({ comp, color: new Color(comp.lightColor.r, comp.lightColor.g, comp.lightColor.b, 1) });
        }
        const glow = this.find('Cat Disco Light');
        this.glow = glow && glow.getComponent ? glow.getComponent(PointLight) : null;
        this.pose = 'stand';    // stand, sit, nap, watch, groom, happy, curious or hide
        this.phase = 0;
        this.clock = 0;
        this.puffs = [];
        this.bits = [];
        this.puffAt = 0;
        this.puffedUntil = -1;
        this.meowUntil = -1;
        this.mouth = 0;
        this.bob = 0;
        this.dance = null;
    }

    /** Writes a fact key once the value held for `hold` seconds. */
    fact(key, value, hold = 0.4) {
        this.seen ??= {};
        const s = this.seen[key];
        if (!s || s.value !== value) {
            this.seen[key] = { value, since: this.time.elapsed };
            return;
        }
        if (this.time.elapsed - s.since >= hold) this.blackboard.set(key, value);
    }

    /** How far the visitor is, on the ground. */
    visitorDistance() {
        const me = this.character;
        const visitor = this.player && this.getCharacter(this.player);
        return me && visitor ? Math.hypot(visitor.feet[0] - me.feet[0], visitor.feet[2] - me.feet[2]) : Infinity;
    }

    update(dt) {
        this.clock += dt;
        const me = this.character;
        const visitor = this.player && this.getCharacter(this.player);
        if (this.blackboard && me && visitor) {
            if (!this.keyed) {
                this.blackboard.set('visitor', this.player);
                this.blackboard.set('hide_spot', this.find('Side Bench'));
                this.keyed = true;
            }
            const d = this.visitorDistance();
            const moving = visitor.mode === 'run' ? 'running' : visitor.mode === 'idle' ? 'still' : 'walking';
            this.fact('dist', d < 1.6 ? 'near' : d < 4.5 ? 'mid' : 'far');
            this.fact('visitor_moving', moving);
            // Someone running close by scares it for a while (not while it dances).
            if (moving === 'running' && d < 3.5 && !this.dance) this.scaredUntil = this.time.elapsed + 8;
            this.fact('scared', this.time.elapsed < (this.scaredUntil ?? -1), 0);
            this.switch ??= this.getScript('Wall Switch', 'FluorescentSwitch');
            this.fact('lights_on', this.switch ? this.switch.on !== false : true);
            // A can from the vending machine put down on the floor.
            if (this.can && !this.canKeyed) {
                this.blackboard.set('can', this.can.object3D);
                this.canKeyed = true;
            }
            this.blackboard.set('can_down', !!this.can && this.can.state === 'floor');
        }
        this.animate(dt);
        this.drift(dt);
        this.flutter(dt);
    }

    /** The model's renderer that can open its mouth (its one morph target), once it has loaded. */
    face() {
        if (!this.renderer && this.figure && this.figure.getComponentsInChild) {
            this.renderer = this.figure.getComponentsInChild(MeshRenderer).find((r) => r.morphData && r.morphData.enable) ?? null;
        }
        return this.renderer;
    }

    animate(dt) {
        const speed = this.character ? this.character.speed : 0;
        const moving = speed > 0.06;
        // Happy (going round a visitor's legs) stays happy on the move.
        const pose = this.dance ? 'dance' : moving && this.pose !== 'happy' ? 'walk' : this.pose;
        const k = 1 - Math.exp(-dt * 10);
        const ease = (o, key, to) => { if (o) o[key] += (to - o[key]) * k; };
        const r = this.rest;
        const b = this.figure;
        const s = this.spinner;
        this.phase += dt * (moving ? 8 + speed * 6 : 0);

        // The OIIA spin: turned and bounced as the model's own animation has
        // it, its mouth wide open, confetti as it starts and as it ends, and the
        // lights changing color on every beat.
        let turn = 0, bounce = 0, open = this.time.elapsed < this.meowUntil ? 0.7 : 0;
        const d = this.dance;
        if (d) {
            d.t += dt;
            const at = Math.min(d.t / SPIN.step, SPIN.turn.length - 1);
            const i = Math.floor(at);
            const j = Math.min(i + 1, SPIN.turn.length - 1);
            const f = at - i;
            turn = SPIN.turn[i] + (SPIN.turn[j] - SPIN.turn[i]) * f;
            bounce = (SPIN.bob[i] + (SPIN.bob[j] - SPIN.bob[i]) * f) * 0.01 * r.sy;
            if (d.t < SPIN.length) {
                open = 1;
                const beat = Math.floor(d.t / BEAT);
                if (beat !== d.beat) {
                    d.beat = beat;
                    this.disco(beat);
                    if (beat === 0) this.confetti(14);
                }
            } else if (!d.burst) {
                d.burst = true;
                this.confetti(30);
            }
        }
        // The bounce eases into the dance and out of it.
        this.bob += (bounce - this.bob) * (1 - Math.exp(-dt * 20));
        if (s) {
            s.rotationY = turn;
            // It hops along as it walks and bounces when it is happy.
            const hop = moving ? Math.abs(Math.sin(this.phase)) * 0.016 : pose === 'happy' ? Math.abs(Math.sin(this.clock * 7)) * 0.02 : 0;
            s.y = r.y + this.bob + hop;
        }

        // The body: tipped, squashed and swayed into each pose.
        let rx = 0, ry = 0, rz = 0, sx = 1, sy = 1;
        if (pose === 'walk') rz = Math.sin(this.phase) * 3;
        else if (pose === 'nap') { const breath = 1 + Math.sin(this.clock * 1.7) * 0.03; sx = 1.05 * breath; sy = 0.86 * breath; }
        else if (pose === 'hide') { sx = 1.07; sy = 0.8; rz = Math.sin(this.clock * 40) * 1.2; }
        else if (pose === 'sit') rx = -8;
        else if (pose === 'watch') { rz = Math.sin(this.clock * 2.6) * 6; ry = Math.sin(this.clock * 1.3) * 10; }
        else if (pose === 'groom') rx = 6 + Math.sin(this.clock * 9) * 3;
        else if (pose === 'curious') { rz = 10; rx = -4; }
        else if (pose === 'happy') rz = Math.sin(this.clock * 3) * 4;
        // Puffed up when scared.
        const puff = this.time.elapsed < this.puffedUntil ? 1.12 : 1;
        if (b) {
            ease(b, 'rotationX', rx);
            ease(b, 'rotationY', ry);
            ease(b, 'rotationZ', rz);
            ease(b, 'scaleX', r.sx * sx * puff);
            ease(b, 'scaleY', r.sy * sy * puff);
            ease(b, 'scaleZ', r.sz * sx * puff);
        }

        // Its mouth (the model's morph target).
        const target = open;
        this.mouth += (target - this.mouth) * (1 - Math.exp(-dt * 25));
        const face = this.face();
        if (face && Math.abs(this.mouth - (this.shown ?? -1)) > 0.01) {
            face.setMorphInfluenceIndex(0, this.mouth);
            this.shown = this.mouth;
        }

        // A zzz while it naps, hearts while it is happy.
        if (this.clock > this.puffAt) {
            if (pose === 'nap') {
                this.puff('#e2ebff', 0.6, 0.018, 0.07);
                this.puffAt = this.clock + 1.1;
            } else if (pose === 'happy') {
                this.puff('#ff8fb1', 0.9, 0.022, 0.16);
                this.puffAt = this.clock + 0.5;
            }
        }
    }

    /** Over its head, a little in front: where hearts, zzz and confetti come from. */
    headPoint() {
        const me = this.character;
        const w = this.object3D.transform.worldPosition;
        const a = ((me ? me.facing : 0) * Math.PI) / 180;
        const k = this.rest.sy;
        return [w.x + Math.sin(a) * 0.2 * k, (me ? me.feet[1] : w.y) + 0.38 * k, w.z + Math.cos(a) * 0.2 * k];
    }

    /** The lights change color on every beat: a rainbow across the ceiling, and its own light. */
    disco(n) {
        const hue = (n * 0.13) % 1;
        const rgb = (h) => {
            const f = (k) => { const x = (k + h * 6) % 6; return 1 - Math.max(0, Math.min(1, Math.min(x, 4 - x))); };
            return new Color(0.3 + 0.7 * f(5), 0.3 + 0.7 * f(3), 0.3 + 0.7 * f(1), 1);
        };
        this.lights.forEach((l, i) => { l.comp.lightColor = rgb(hue + i * 0.11); });
        if (this.glow) {
            this.glow.lightColor = rgb(hue + 0.5);
            this.glow.intensity = 2.4;
        }
    }

    /** The lights back as they were. */
    discoOff() {
        for (const l of this.lights) l.comp.lightColor = new Color(l.color.r, l.color.g, l.color.b, 1);
        if (this.glow) this.glow.intensity = 0;
    }

    /** A burst of confetti from over its head. */
    confetti(n) {
        const [x, y, z] = this.headPoint();
        for (let i = 0; i < n; i++) {
            const color = CONFETTI[Math.floor(Math.random() * CONFETTI.length)];
            const s = 0.018 + Math.random() * 0.016;
            const obj = this.spawn('box', { name: 'Cat Confetti', color, scale: [s, s * 0.3, s * 1.4], position: [x, y + 0.05, z] });
            this.setEmissive(color, 0.5, obj);
            const a = Math.random() * Math.PI * 2;
            const v = 0.5 + Math.random() * 0.9;
            this.bits.push({ obj, vx: Math.cos(a) * v, vy: 1.4 + Math.random() * 1.2, vz: Math.sin(a) * v, turn: (Math.random() - 0.5) * 900, age: 0, size: s });
        }
    }

    /** Confetti flutters down, lies a moment on the floor and is gone. */
    flutter(dt) {
        const floor = (this.character ? this.character.feet[1] : 0) + 0.004;
        for (const b of this.bits) {
            b.age += dt;
            b.vy = Math.max(-0.7, b.vy - 5.5 * dt);
            b.vx *= 1 - dt * 1.2;
            b.vz *= 1 - dt * 1.2;
            const o = b.obj;
            o.x += b.vx * dt;
            o.z += b.vz * dt;
            o.y += b.vy * dt;
            if (o.y <= floor) {
                o.y = floor;
                b.vx = b.vz = b.vy = b.turn = 0;
            }
            o.rotationX += b.turn * dt;
            o.rotationZ += b.turn * 0.7 * dt;
            const s = b.size * Math.max(0.0001, Math.min(1, (3 - b.age) / 0.5));
            o.scaleX = s;
            o.scaleY = s * 0.3;
            o.scaleZ = s * 1.4;
        }
        for (const b of this.bits) if (b.age > 3) this.destroy(b.obj);
        this.bits = this.bits.filter((b) => b.age <= 3);
    }

    /** A little glowing ball rising from over its head. */
    puff(color, glow, size, rise) {
        const [x, y, z] = this.headPoint();
        const obj = this.spawn('sphere', { name: 'Cat Puff', color, scale: [size, size, size], position: [x + (Math.random() - 0.5) * 0.06, y, z + (Math.random() - 0.5) * 0.06] });
        this.setEmissive(color, glow, obj);
        this.puffs.push({ obj, age: 0, size, rise, sway: Math.random() * 6.28 });
    }

    /** The puffs rise, sway and shrink away. */
    drift(dt) {
        for (const p of this.puffs) {
            p.age += dt;
            p.obj.y += p.rise * dt;
            p.obj.x += Math.sin(p.age * 3 + p.sway) * 0.04 * dt;
            const s = p.size * Math.min(1, p.age * 4) * Math.max(0, 1 - Math.max(0, p.age - 1.1) / 0.6);
            p.obj.scaleX = p.obj.scaleY = p.obj.scaleZ = Math.max(0.0001, s);
        }
        for (const p of this.puffs) if (p.age > 1.7) this.destroy(p.obj);
        this.puffs = this.puffs.filter((p) => p.age <= 1.7);
    }

    // Tasks of the tree (Script Task nodes name these methods).

    /** At the can: it takes it, and the tree's oiia branch takes over. */
    takeCan() {
        if (!this.can || this.can.state !== 'floor') return false;
        this.lookAt(this.can.object3D);
        this.can.taken(this.object3D);
        this.blackboard?.set('treat', true);
        return true;
    }

    /** The OIIA spin while the lights go disco, then hearts. */
    async oiia(task) {
        if (this.player) this.lookAt(this.player);
        this.pose = 'stand';
        this.dance = { t: 0, beat: -1 };
        const ok = await this.hold(task, SPIN.length + 0.2);
        this.dance = null;
        this.discoOff();
        const done = ok && (await this.hold(task, 1.6, 'happy'));
        this.blackboard?.set('treat', false);
        return done;
    }

    /** What to do next and where: nap by the heater, watch a turning washer, look out at the rain, or wash on the bench. */
    pickSpot(task) {
        const options = [];
        const heater = this.find('Heater');
        if (heater) options.push({ obj: heater, what: 'nap', weight: 3 });
        for (let i = 1; i <= 8; i++) {
            const washer = this.find('Washer ' + i);
            const s = washer && this.getScript(washer, 'Washer');
            const p = s && typeof s.phase === 'function' ? s.phase() : '';
            if (p === 'wash' || p === 'spin') options.push({ obj: washer, what: 'washer', weight: 0.6 });
        }
        const mat = this.find('Door Mat');
        if (mat) options.push({ obj: mat, what: 'rain', weight: 1.5 });
        const bench = this.find('Bench 1');
        if (bench) options.push({ obj: bench, what: 'groom', weight: 1.2 });
        // Not the same thing twice in a row.
        const pool = options.filter((o) => o.what !== this.lastWhat);
        const from = pool.length ? pool : options;
        let r = Math.random() * from.reduce((n, o) => n + o.weight, 0);
        const pick = from.find((o) => (r -= o.weight) <= 0) ?? from[0];
        if (!pick) return false;
        this.activity = pick;
        this.lastWhat = pick.what;
        task.set('spot', pick.obj);
        return true;
    }

    /** Does what it came for. */
    settle(task) {
        const a = this.activity;
        if (!a) return false;
        if (a.what === 'washer') this.lookAt(a.obj);
        if (a.what === 'rain') this.lookAt(this.find('Automatic Door') ?? a.obj);
        const pose = a.what === 'nap' ? 'nap' : a.what === 'washer' ? 'watch' : a.what === 'rain' ? 'sit' : 'groom';
        return this.hold(task, a.what === 'nap' ? 12 + Math.random() * 8 : 5 + Math.random() * 4, pose);
    }

    /** Someone ran close by: it puffs up, hisses and jumps. */
    spook(task) {
        this.puffedUntil = this.time.elapsed + 4;
        this.meowUntil = this.time.elapsed + 0.6;
        if (this.player) this.lookAt(this.player);
        this.character?.jump();
        return this.hold(task, 0.5, 'stand');
    }

    /** Under the bench, crouched and peeking out, until it feels safe again (the tree ends this). */
    hide(task) {
        if (this.player) this.lookAt(this.player);
        return this.hold(task, 60, 'hide');
    }

    /** Goes once round the visitor's legs with a meow, hearts rising, then sits and looks up. */
    async rub(task) {
        const visitor = this.player && this.getCharacter(this.player);
        const me = this.character;
        if (!visitor || !me) return false;
        this.pose = 'happy';
        this.meowUntil = this.time.elapsed + 0.5;
        // Eight short steps from where it is, just clear of the visitor's legs.
        const f = visitor.feet;
        const from = Math.atan2(me.feet[0] - f[0], me.feet[2] - f[2]);
        const round = visitor.doc.radius + me.doc.radius + 0.1;
        for (let i = 1; i <= 8; i++) {
            if (task.aborted) break;
            const a = from + (i * Math.PI) / 4;
            await me.moveTo([f[0] + Math.sin(a) * round, f[1], f[2] + Math.cos(a) * round], { radius: 0.1, straight: true, signal: task.signal });
        }
        if (task.aborted) {
            this.pose = 'stand';
            return false;
        }
        this.lookAt(this.player);
        this.meowUntil = this.time.elapsed + 0.5;
        return this.hold(task, 3, 'happy');
    }

    /** Sits and looks at a visitor who stands still, head tilted. */
    watch(task) {
        if (this.player) this.lookAt(this.player);
        return this.hold(task, 2.5 + Math.random() * 2, 'curious');
    }

    /** Resolves true after `seconds` in a pose (back to standing), false when the task is aborted first. */
    hold(task, seconds, pose) {
        if (pose) this.pose = pose;
        return new Promise((resolve) => {
            const done = (ok) => {
                this.pose = 'stand';
                resolve(ok);
            };
            const stop = this.after(seconds, () => done(true));
            task.signal.addEventListener('abort', () => {
                stop();
                done(false);
            }, { once: true });
        });
    }
}

// A can of soda from the vending machine. It waits inside the machine until
// the machine's button is pressed and drops into the tray. Click it (tap it
// on a phone) to pick it up, and click it again in your hand to put it down
// on the floor in front of you. Put it down where the cat can see it and see
// what happens. It is back in the machine after that.
export default class SodaCan extends Script {
    reach = 2.2;        // meters from the player at which it can be picked up

    start() {
        const o = this.object3D;
        this.tray = { x: o.x, y: o.y, z: o.z, rx: o.rotationX, ry: o.rotationY, rz: o.rotationZ };
        this.state = 'stocked';     // stocked, falling, tray, held, floor or taken
        this.t = 0;
        this.show(false);
    }

    /** Out of the machine or hidden in it. */
    show(on) {
        const o = this.object3D;
        o.scaleX = o.scaleY = o.scaleZ = on ? 1 : 0.0001;
    }

    /** The machine sold one: it drops into the tray. False while one is out. */
    drop(seconds) {
        if (this.state !== 'stocked') return false;
        const o = this.object3D;
        o.x = this.tray.x;
        o.z = this.tray.z;
        o.rotationX = this.tray.rx;
        o.rotationY = this.tray.ry;
        o.rotationZ = this.tray.rz;
        this.state = 'falling';
        this.fall = seconds;
        this.t = 0;
        this.show(true);
        return true;
    }

    // In the tray or on the floor a click picks it up; in the hand a click puts it down.
    onClick() {
        if (this.state === 'held') return this.putDown();
        if (this.state !== 'tray' && this.state !== 'floor') return;
        const player = this.getCharacter('Player');
        if (!player || Math.hypot(player.feet[0] - this.object3D.x, player.feet[2] - this.object3D.z) > this.reach) return;
        this.state = 'held';
    }

    /** On the floor, upright, a little in front of the player. */
    putDown() {
        const player = this.getCharacter('Player');
        if (!player) return;
        const m = this.camera.transform.worldMatrix.rawData;
        const len = Math.hypot(m[8], m[10]) || 1;
        const o = this.object3D;
        o.x = player.feet[0] + (m[8] / len) * 0.7;
        o.z = player.feet[2] + (m[10] / len) * 0.7;
        o.y = player.feet[1] + 0.061;
        o.rotationX = 0;
        o.rotationZ = 0;
        this.state = 'floor';
    }

    /** Taken by `target` (the cat): it hops to its mouth and is gone. */
    taken(target) {
        const o = this.object3D;
        this.from = [o.x, o.y, o.z];
        this.target = target;
        this.state = 'taken';
        this.t = 0;
    }

    update(dt) {
        const o = this.object3D;
        this.t += dt;
        if (this.state === 'falling') {
            // Down from behind the flap into the tray, with a little bounce.
            const k = Math.min(1, this.t / this.fall);
            const bounce = k >= 1 ? Math.max(0, Math.sin((this.t - this.fall) * 18)) * 0.03 * Math.max(0, 1 - (this.t - this.fall) * 4) : 0;
            o.y = this.tray.y + (1 - k * k) * 0.24 + bounce;
            if (this.t > this.fall + 0.3) {
                o.y = this.tray.y;
                this.state = 'tray';
            }
        } else if (this.state === 'held') {
            // In the right hand, a little below the middle of the view, upright (the view's right is its matrix's -x).
            const m = this.camera.transform.worldMatrix.rawData;
            o.x = m[12] - m[0] * 0.14 - m[4] * 0.11 + m[8] * 0.42;
            o.y = m[13] - m[1] * 0.14 - m[5] * 0.11 + m[9] * 0.42;
            o.z = m[14] - m[2] * 0.14 - m[6] * 0.11 + m[10] * 0.42;
            o.rotationX = 0;
            o.rotationY = (Math.atan2(m[8], m[10]) * 180) / Math.PI;
            o.rotationZ = 10;
        } else if (this.state === 'taken') {
            // A hop to the cat's mouth, tumbling, then it is gone.
            const k = Math.min(1, this.t / 0.4);
            const w = this.target.transform.worldPosition;
            const [fx, fy, fz] = this.from;
            o.x = fx + (w.x - fx) * k;
            o.z = fz + (w.z - fz) * k;
            o.y = fy + (w.y + 0.2 - fy) * k + Math.sin(Math.PI * k) * 0.2;
            o.rotationX += 720 * dt;
            const s = Math.max(0.0001, 1 - Math.max(0, (this.t - 0.35) / 0.2));
            o.scaleX = o.scaleY = o.scaleZ = s;
            if (this.t > 0.55) {
                // Back in the machine for the next one.
                o.x = this.tray.x;
                o.y = this.tray.y;
                o.z = this.tray.z;
                this.show(false);
                this.state = 'stocked';
            }
        }
    }
}

// The vending machine's button: click it (tap it on a phone) and a can of
// soda drops into the tray at the bottom, one at a time. It pulses while a
// can is waiting in the machine and flashes when it sells one.
export default class VendingMachine extends Script {
    dropTime = 0.4;     // seconds the can takes to fall into the tray

    start() {
        this.can = this.getScript('Soda Can', 'SodaCan');
        this.lit = 0;
        this.glow = -1;
    }

    onClick() {
        if (!this.can || !this.can.drop(this.dropTime)) return;
        this.lit = 0.6;
    }

    update(dt) {
        this.lit = Math.max(0, this.lit - dt);
        const ready = this.can && this.can.state === 'stocked';
        const glow = this.lit > 0 ? 5 : ready ? 1.6 + Math.sin(this.time.elapsed * 3) * 0.9 : 0.5;
        if (Math.abs(glow - this.glow) > 0.05) {
            this.glow = glow;
            this.setEmissive(this.lit > 0 ? '#9dffe0' : '#2dd4bf', glow);
        }
    }
}

