// World space triplanar surface (@morglay triplanar): the albedo, normal
// and ARM (occlusion, roughness, metallic) textures are projected along x, y
// and z and blended by the surface normal, so they keep their real size on
// every mesh. tile is the size of one texture tile in meters. Only the
// projections a surface faces are read: a floor or a wall reads each texture
// once. maps says which textures there are (1: normal, 2: ARM); roughness and
// metallic multiply the ARM map's.
// @property albedo texture white
// @property normalTex texture normal
// @property armTex texture data
// @property tile float 2 0.05 50
// @property sharpness float 4 1 16
// @property normalStrength float 1 0 2
// @property maps float 0 0 3

struct Triplanar {
    color: vec4f,
    arm: vec3f,
    // The normal maps' slope, in world space.
    bump: vec3f,
};

fn triplanarSample(p: vec3f, n: vec3f) -> Triplanar {
    let s = 1.0 / max(materialUniform.tile, 0.001);
    var w = pow(abs(n), vec3f(materialUniform.sharpness));
    w = w / max(w.x + w.y + w.z, 0.0001);
    // Leave out the projections that barely count, then weigh the rest to one.
    w = select(vec3f(0.0), w, w > vec3f(0.02));
    w = w / max(w.x + w.y + w.z, 0.0001);
    // Gradients while every pixel runs here: the projections below read
    // only where they weigh (textureSampleGrad needs no uniform flow).
    let dx = dpdx(p) * s;
    let dy = dpdy(p) * s;
    let flags = u32(materialUniform.maps + 0.5);
    let useNormal = (flags & 1u) != 0u;
    let useArm = (flags & 2u) != 0u;
    var out: Triplanar;
    out.color = vec4f(0.0);
    out.arm = vec3f(0.0);
    out.bump = vec3f(0.0);
    // Along x: u east (+z), up the image +y.
    if (w.x > 0.0) {
        let uv = vec2f(p.z, -p.y) * s;
        let gx = vec2f(dx.z, -dx.y);
        let gy = vec2f(dy.z, -dy.y);
        out.color += textureSampleGrad(albedo, albedoSampler, uv, gx, gy) * w.x;
        out.arm += select(vec3f(1.0), textureSampleGrad(armTex, armTexSampler, uv, gx, gy).rgb, useArm) * w.x;
        if (useNormal) {
            let t = textureSampleGrad(normalTex, normalTexSampler, uv, gx, gy).xy * 2.0 - 1.0;
            out.bump += (t.x * vec3f(0.0, 0.0, 1.0) + t.y * vec3f(0.0, 1.0, 0.0)) * w.x;
        }
    }
    // Along y: u +x, up the image -z.
    if (w.y > 0.0) {
        let uv = vec2f(p.x, p.z) * s;
        let gx = vec2f(dx.x, dx.z);
        let gy = vec2f(dy.x, dy.z);
        out.color += textureSampleGrad(albedo, albedoSampler, uv, gx, gy) * w.y;
        out.arm += select(vec3f(1.0), textureSampleGrad(armTex, armTexSampler, uv, gx, gy).rgb, useArm) * w.y;
        if (useNormal) {
            let t = textureSampleGrad(normalTex, normalTexSampler, uv, gx, gy).xy * 2.0 - 1.0;
            out.bump += (t.x * vec3f(1.0, 0.0, 0.0) + t.y * vec3f(0.0, 0.0, -1.0)) * w.y;
        }
    }
    // Along z: u +x, up the image +y.
    if (w.z > 0.0) {
        let uv = vec2f(p.x, -p.y) * s;
        let gx = vec2f(dx.x, -dx.y);
        let gy = vec2f(dy.x, -dy.y);
        out.color += textureSampleGrad(albedo, albedoSampler, uv, gx, gy) * w.z;
        out.arm += select(vec3f(1.0), textureSampleGrad(armTex, armTexSampler, uv, gx, gy).rgb, useArm) * w.z;
        if (useNormal) {
            let t = textureSampleGrad(normalTex, normalTexSampler, uv, gx, gy).xy * 2.0 - 1.0;
            out.bump += (t.x * vec3f(1.0, 0.0, 0.0) + t.y * vec3f(0.0, 1.0, 0.0)) * w.z;
        }
    }
    return out;
}

fn frag() {
    let n = normalize(ORI_VertexVarying.vWorldNormal);
    let p = ORI_VertexVarying.vWorldPos.xyz;
    let t = triplanarSample(p, n);
    let c = t.color * materialUniform.baseColor;
    ORI_ShadingInput.BaseColor = vec4f(c.rgb, materialUniform.baseColor.a);
    ORI_ShadingInput.Roughness = clamp(t.arm.g * materialUniform.roughness, 0.02, 1.0);
    ORI_ShadingInput.Metallic = t.arm.b * materialUniform.metallic;
    ORI_ShadingInput.Specular = 1.0;
    ORI_ShadingInput.AmbientOcclusion = t.arm.r;
    ORI_ShadingInput.EmissiveColor = vec4f(materialUniform.emissiveColor.rgb, 1.0);
    ORI_ShadingInput.Normal = normalize(n + t.bump * materialUniform.normalStrength);
    useShadow();
    BxDFShading();
}

// Water for a flat surface (a plane). mirrorColor(offset) is the scene a
// Mirror component on the object reflects, moved by offset (screen units);
// its alpha is 0 without one, and the sky is reflected instead.
// @property deepColor color #0b2a36
// @property shallowColor color #1f5e66
// @property waveScale float 1 0.05 5
// @property waveSpeed float 1 0 5
// @property waveHeight float 0.15 0 1
// @property distortion float 0.03 0 0.2
// @property reflectivity float 1 0 1

// Slopes of three waves across the surface.
fn waveSlope(p: vec2f, t: f32) -> vec2f {
    let k = materialUniform.waveScale;
    var s = vec2f(0.8, 0.6) * cos(dot(p, vec2f(0.8, 0.6)) * 1.1 * k + t * 1.2);
    s += vec2f(-0.5, 0.87) * cos(dot(p, vec2f(-0.5, 0.87)) * 2.3 * k - t * 1.7) * 0.5;
    s += vec2f(0.28, -0.96) * cos(dot(p, vec2f(0.28, -0.96)) * 4.9 * k + t * 2.3) * 0.25;
    return s * materialUniform.waveHeight;
}

fn frag() {
    let p = ORI_VertexVarying.vWorldPos.xyz;
    let slope = waveSlope(p.xz, getTime() * materialUniform.waveSpeed);
    let n = normalize(vec3f(-slope.x, 1.0, -slope.y));
    let v = normalize(globalUniform.CameraPos.xyz - p);
    let nv = max(dot(n, v), 0.0);
    let fresnel = 0.02 + 0.98 * pow(1.0 - nv, 5.0);
    let r = reflect(-v, n);

    // The mirrored scene where there is one, else the sky.
    let mirror = mirrorColor(n.xz * materialUniform.distortion);
    let sky = textureSampleLevel(prefilterMap, prefilterMapSampler, r, 0.0).rgb * globalUniform.skyExposure;
    let reflection = mix(sky, mirror.rgb, mirror.a) * materialUniform.reflectivity;
    let sun = lightBuffer[0];
    let glint = pow(max(dot(r, -normalize(sun.direction)), 0.0), 600.0) * sun.lightColor.rgb * sun.intensity * 8.0;

    ORI_ShadingInput.BaseColor = vec4f(mix(materialUniform.deepColor.rgb, materialUniform.shallowColor.rgb, sqrt(nv)) * (1.0 - fresnel), 1.0);
    // Rough, so the lighting adds no reflection of its own over this one.
    ORI_ShadingInput.Roughness = 1.0;
    ORI_ShadingInput.Metallic = 0.0;
    ORI_ShadingInput.Specular = 0.0;
    ORI_ShadingInput.AmbientOcclusion = 1.0;
    ORI_ShadingInput.Normal = n;
    useShadow();
    // Emission is read as gamma-encoded color: encode the linear light.
    let light = reflection * fresnel + glint * directShadowVisibility[0];
    ORI_ShadingInput.EmissiveColor = vec4f(pow(max(light, vec3f(0.0)), vec3f(1.0 / 2.4)), 1.0);
    BxDFShading();
}

// Post shader: return the new color for screen position uv (0..1).
// sceneColor(uv) reads the image produced by the passes before this one.
// @property strength float 0.6 0 2
// @property radius float 0.75 0.1 1.5
// @property tint color #000000

fn post(uv: vec2f) -> vec4f {
    let c = sceneColor(uv);
    let d = distance(uv, vec2f(0.5));
    let v = smoothstep(materialUniform.radius, materialUniform.radius - 0.45, d);
    let k = mix(1.0, v, materialUniform.strength);
    return vec4f(mix(materialUniform.tint.rgb, c.rgb, clamp(k, 0.0, 1.0)), c.a);
}

// Post shader: lift, gamma and gain, then saturation. It works on the HDR
// image before tone mapping: lift raises the darks, gamma bends the mid
// tones, gain scales everything. x, y, z are red, green and blue; w applies
// to all three (lift and gain add / multiply it, gamma multiplies it).
// @property lift vec4 0 0 0 0
// @property gamma vec4 1 1 1 1
// @property gain vec4 1 1 1 1
// @property saturation float 1 0 2

fn post(uv: vec2f) -> vec4f {
    let c = sceneColor(uv);
    let lift = materialUniform.lift.xyz + vec3f(materialUniform.lift.w);
    let gamma = max(materialUniform.gamma.xyz * materialUniform.gamma.w, vec3f(0.01));
    let gain = materialUniform.gain.xyz * materialUniform.gain.w;
    var x = max(c.rgb, vec3f(0.0));
    x = x + lift * max(vec3f(1.0) - x, vec3f(0.0));
    x = max(x * gain, vec3f(0.0));
    x = pow(x, vec3f(1.0) / gamma);
    let luma = dot(x, vec3f(0.2126, 0.7152, 0.0722));
    x = mix(vec3f(luma), x, materialUniform.saturation);
    return vec4f(max(x, vec3f(0.0)), c.a);
}

// Post shader: return the new color for screen position uv (0..1).
// sceneColor(uv) reads the image produced by the passes before this one.
//
// Vignette and colour grade in ONE pass: the vignette darkens the frame edges,
// then lift raises the darks, gamma bends the mid tones, gain scales
// everything and saturation pulls the colours in or out. Both halves are per
// pixel, so running them in one shader is the same image as the two separate
// passes were - it just costs one full screen pass and one render target
// instead of two.
//
// @property strength float 0.6 0 2
// @property radius float 0.75 0.1 1.5
// @property tint color #000000
// @property lift vec4 0 0 0 0
// @property gamma vec4 1 1 1 1
// @property gain vec4 1 1 1 1
// @property saturation float 1 0 2

fn post(uv: vec2f) -> vec4f {
    let c = sceneColor(uv);

    // vignette
    let d = distance(uv, vec2f(0.5));
    let v = smoothstep(materialUniform.radius, materialUniform.radius - 0.45, d);
    let k = mix(1.0, v, materialUniform.strength);
    var x = mix(materialUniform.tint.rgb, c.rgb, clamp(k, 0.0, 1.0));

    // lift, gamma, gain and saturation
    let lift = materialUniform.lift.xyz + vec3f(materialUniform.lift.w);
    let gamma = max(materialUniform.gamma.xyz * materialUniform.gamma.w, vec3f(0.01));
    let gain = materialUniform.gain.xyz * materialUniform.gain.w;
    x = max(x, vec3f(0.0));
    x = x + lift * max(vec3f(1.0) - x, vec3f(0.0));
    x = max(x * gain, vec3f(0.0));
    x = pow(x, vec3f(1.0) / gamma);
    let luma = dot(x, vec3f(0.2126, 0.7152, 0.0722));
    x = mix(vec3f(luma), x, materialUniform.saturation);

    return vec4f(max(x, vec3f(0.0)), c.a);
}

// Wet ground for the top of a floor, a pavement or a road: its texture
// projected in world space (as Triplanar.wgsl), darker and glossier where it
// is wet, puddles where a noise field dips, and the scene a Mirror component
// on the object captures, reflected by a fresnel term: nearly sharp in the
// puddles (rain rings ripple it) and drawn down the screen on the wet ground
// around them, as wet asphalt stretches lights into streaks. Without a
// Mirror it is just the wet surface. The low graphics tier leaves out the
// rain rings and reads half as many taps along the streaks.
// @property albedo texture white
// @property normalTex texture normal
// @property armTex texture data
// @property tile float 2 0.05 50
// @property maps float 0 0 3
// @property wetness float 0.75 0 1
// @property puddles float 0.4 0 1
// @property puddleScale float 0.35 0.02 4
// @property reflection float 1 0 3
// @property streak float 0.03 0 0.15
// @property ripples float 1 0 3
// @property rippleScale float 2.5 0.5 12

struct WgSample {
    color: vec4f,
    arm: vec3f,
    bump: vec3f,
};

fn wgTriplanar(p: vec3f, n: vec3f) -> WgSample {
    let s = 1.0 / max(materialUniform.tile, 0.001);
    var w = pow(abs(n), vec3f(4.0));
    w = w / max(w.x + w.y + w.z, 0.0001);
    w = select(vec3f(0.0), w, w > vec3f(0.02));
    w = w / max(w.x + w.y + w.z, 0.0001);
    let dx = dpdx(p) * s;
    let dy = dpdy(p) * s;
    let flags = u32(materialUniform.maps + 0.5);
    let useNormal = (flags & 1u) != 0u;
    let useArm = (flags & 2u) != 0u;
    var o: WgSample;
    o.color = vec4f(0.0);
    o.arm = vec3f(0.0);
    o.bump = vec3f(0.0);
    if (w.x > 0.0) {
        let uv = vec2f(p.z, -p.y) * s;
        let gx = vec2f(dx.z, -dx.y);
        let gy = vec2f(dy.z, -dy.y);
        o.color += textureSampleGrad(albedo, albedoSampler, uv, gx, gy) * w.x;
        o.arm += select(vec3f(1.0), textureSampleGrad(armTex, armTexSampler, uv, gx, gy).rgb, useArm) * w.x;
        if (useNormal) {
            let t = textureSampleGrad(normalTex, normalTexSampler, uv, gx, gy).xy * 2.0 - 1.0;
            o.bump += (t.x * vec3f(0.0, 0.0, 1.0) + t.y * vec3f(0.0, 1.0, 0.0)) * w.x;
        }
    }
    if (w.y > 0.0) {
        let uv = vec2f(p.x, p.z) * s;
        let gx = vec2f(dx.x, dx.z);
        let gy = vec2f(dy.x, dy.z);
        o.color += textureSampleGrad(albedo, albedoSampler, uv, gx, gy) * w.y;
        o.arm += select(vec3f(1.0), textureSampleGrad(armTex, armTexSampler, uv, gx, gy).rgb, useArm) * w.y;
        if (useNormal) {
            let t = textureSampleGrad(normalTex, normalTexSampler, uv, gx, gy).xy * 2.0 - 1.0;
            o.bump += (t.x * vec3f(1.0, 0.0, 0.0) + t.y * vec3f(0.0, 0.0, -1.0)) * w.y;
        }
    }
    if (w.z > 0.0) {
        let uv = vec2f(p.x, -p.y) * s;
        let gx = vec2f(dx.x, -dx.y);
        let gy = vec2f(dy.x, -dy.y);
        o.color += textureSampleGrad(albedo, albedoSampler, uv, gx, gy) * w.z;
        o.arm += select(vec3f(1.0), textureSampleGrad(armTex, armTexSampler, uv, gx, gy).rgb, useArm) * w.z;
        if (useNormal) {
            let t = textureSampleGrad(normalTex, normalTexSampler, uv, gx, gy).xy * 2.0 - 1.0;
            o.bump += (t.x * vec3f(1.0, 0.0, 0.0) + t.y * vec3f(0.0, 1.0, 0.0)) * w.z;
        }
    }
    return o;
}

fn wgHash(p: vec2f) -> f32 {
    var q = fract(p * vec2f(0.1031, 0.1030));
    q += dot(q, q.yx + 33.33);
    return fract((q.x + q.y) * q.x);
}

fn wgNoise(p: vec2f) -> f32 {
    let i = floor(p);
    let f = p - i;
    let u = f * f * (3.0 - 2.0 * f);
    let a = wgHash(i);
    let b = wgHash(i + vec2f(1.0, 0.0));
    let c = wgHash(i + vec2f(0.0, 1.0));
    let d = wgHash(i + vec2f(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn wgFbm(p: vec2f) -> f32 {
    return wgNoise(p) * 0.5 + wgNoise(p * 2.07 + vec2f(17.1, 3.7)) * 0.3 + wgNoise(p * 4.31 + vec2f(5.3, 11.9)) * 0.2;
}

// Rain rings: a drop lands in every cell at its own time and its ring
// spreads and fades. The slope of the rings around p (p in cells).
fn wgRipples(p: vec2f, t: f32) -> vec2f {
    var slope = vec2f(0.0);
    let base = floor(p);
    for (var j = -1; j <= 1; j++) {
        for (var i = -1; i <= 1; i++) {
            let cell = base + vec2f(f32(i), f32(j));
            let center = cell + 0.15 + 0.7 * vec2f(wgHash(cell + vec2f(7.3, 1.1)), wgHash(cell + vec2f(3.1, 9.7)));
            let life = fract(t * 0.8 + wgHash(cell));
            let d = p - center;
            let r = length(d);
            let x = (r - life * 1.2) * 18.0;
            let ring = sin(x) * exp(-x * x * 0.08) * (1.0 - life) * (1.0 - life);
            slope += d / max(r, 0.001) * ring;
        }
    }
    return slope;
}

fn frag() {
    let n0 = normalize(ORI_VertexVarying.vWorldNormal);
    let p = ORI_VertexVarying.vWorldPos.xyz;
    let t = wgTriplanar(p, n0);
    // Only the top lies wet; the sides stay as they are.
    let top = smoothstep(0.7, 0.95, n0.y);
    let field = wgFbm(p.xz * materialUniform.puddleScale);
    let edge = 1.0 - materialUniform.puddles;
    let puddle = top * smoothstep(edge - 0.04, edge + 0.04, field) * step(0.001, materialUniform.puddles);
    let wet = clamp(materialUniform.wetness * top + puddle, 0.0, 1.0);
    var slope = vec2f(0.0);
    if (qualityTier() > 0 && puddle > 0.01 && materialUniform.ripples > 0.0) {
        slope = wgRipples(p.xz * materialUniform.rippleScale, getTime()) * materialUniform.ripples * puddle;
    }
    let n = normalize(n0 + t.bump * (1.0 - puddle) + vec3f(slope.x, 0.0, slope.y) * 0.08);
    // Water fills the pores: a wet surface is darker, a puddle more so.
    let c = t.color.rgb * materialUniform.baseColor.rgb;
    let base = c * mix(1.0, 0.5, wet) * mix(1.0, 0.7, puddle);
    let dryRough = clamp(t.arm.g * materialUniform.roughness, 0.02, 1.0);
    let rough = mix(mix(dryRough, dryRough * 0.6, wet), 0.03, puddle);

    // The reflection: nearly sharp in a puddle, a streak down the screen on wet ground.
    let v = normalize(globalUniform.CameraPos.xyz - p);
    let nv = clamp(dot(n, v), 0.0, 1.0);
    let F = 0.02 + 0.98 * pow(1.0 - nv, 5.0);
    let len = mix(materialUniform.streak, materialUniform.streak * 0.12, puddle);
    let off = slope * 0.01;
    // Taps along the streak, each pixel starting at its own random point so a
    // small bright light smears instead of repeating in steps.
    let jitter = wgHash(mirrorUV() * vec2f(1931.0, 1213.0));
    let taps = select(4, 8, qualityTier() > 0);
    var refl = vec3f(0.0);
    var cover = 0.0;
    for (var k = 0; k < taps; k++) {
        let m = mirrorColor(off + vec2f(0.0, ((f32(k) + jitter) / f32(taps) - 0.2) * len));
        refl += m.rgb;
        cover += m.a;
    }
    refl = refl / f32(taps);
    cover = cover / f32(taps);
    let amount = F * materialUniform.reflection * top * mix(wet * 0.55, 1.0, puddle);

    ORI_ShadingInput.BaseColor = vec4f(base, 1.0);
    ORI_ShadingInput.Roughness = rough;
    ORI_ShadingInput.Metallic = 0.0;
    // Where the mirror gives the reflection, the surface's own sky reflection steps back.
    ORI_ShadingInput.Specular = mix(1.0, 0.3, clamp(cover, 0.0, 1.0) * puddle);
    ORI_ShadingInput.AmbientOcclusion = t.arm.r;
    ORI_ShadingInput.EmissiveColor = vec4f(materialUniform.emissiveColor.rgb, 1.0);
    ORI_ShadingInput.Normal = n;
    useShadow();
    BxDFShading();
    ORI_FragmentOutput.color = vec4f(ORI_FragmentOutput.color.rgb + refl * amount, ORI_FragmentOutput.color.a);
}

// Wire mesh: thin wires on a square grid with the gaps cut out, for
// baskets, carts, grilles and fences. The grid lies in world space on each
// face of the mesh (make the material double sided to see the far faces
// through the near ones). cell: meters between wires; wire: their width.
// @property cell float 0.045 0.005 1
// @property wire float 0.006 0.001 0.1

fn frag() {
    let p = ORI_VertexVarying.vWorldPos.xyz;
    let n = normalize(ORI_VertexVarying.vWorldNormal);
    let a = abs(n);
    var uv = p.xy;
    if (a.x >= a.y && a.x >= a.z) {
        uv = p.zy;
    } else if (a.y >= a.z) {
        uv = p.xz;
    }
    let cell = materialUniform.cell;
    // Never thinner than about a pixel, so far wires do not break up.
    let px = length(fwidth(uv));
    let hw = max(materialUniform.wire * 0.5, px * 0.5);
    let g = abs(fract(uv / cell + 0.5) - 0.5) * cell;
    let d = min(g.x, g.y);
    if (d > hw) {
        discard;
    }
    ORI_ShadingInput.BaseColor = vec4f(materialUniform.baseColor.rgb, 1.0);
    ORI_ShadingInput.Roughness = materialUniform.roughness;
    ORI_ShadingInput.Metallic = materialUniform.metallic;
    ORI_ShadingInput.Specular = 1.0;
    ORI_ShadingInput.AmbientOcclusion = 1.0;
    ORI_ShadingInput.EmissiveColor = vec4f(materialUniform.emissiveColor.rgb, 1.0);
    ORI_ShadingInput.Normal = n;
    useShadow();
    BxDFShading();
}

// Vending machine front: shelves of lit products behind glass. center and
// size give the window on the panel's front face in world space (x, y);
// rows and cols the grid of products; glow how bright the lit back is.
// @property center vec4 3.7 1.57 0 0
// @property size vec4 0.86 1 0 0
// @property rows float 6 1 12
// @property cols float 6 1 12
// @property glow float 1.2 0 6

fn vmHash(p: vec2f) -> f32 {
    var q = fract(p * vec2f(0.1031, 0.1030));
    q += dot(q, q.yx + 33.33);
    return fract((q.x + q.y) * q.x);
}

// A label color: reds, oranges, pinks, cyans, yellows and whites.
fn vmLabel(h: f32) -> vec3f {
    let k = u32(h * 6.0) % 6u;
    var c = vec3f(0.92, 0.92, 0.95);
    switch k {
        case 0u: { c = vec3f(0.95, 0.18, 0.2); }
        case 1u: { c = vec3f(1.0, 0.55, 0.12); }
        case 2u: { c = vec3f(1.0, 0.3, 0.65); }
        case 3u: { c = vec3f(0.2, 0.8, 0.95); }
        case 4u: { c = vec3f(1.0, 0.88, 0.25); }
        default: { c = vec3f(0.92, 0.92, 0.95); }
    }
    return c;
}

fn frag() {
    let p = ORI_VertexVarying.vWorldPos.xyz;
    let n = normalize(ORI_VertexVarying.vWorldNormal);
    let uv = (p.xy - materialUniform.center.xy) / max(materialUniform.size.xy, vec2f(0.01)) + 0.5;
    let g = vec2f(uv.x * materialUniform.cols, uv.y * materialUniform.rows);
    let id = floor(g);
    let f = g - id;
    let h = vmHash(id + vec2f(0.37, 0.71));
    let w = 0.5 + 0.3 * vmHash(id + vec2f(1.7, 2.9));
    let ht = 0.45 + 0.35 * vmHash(id + vec2f(4.1, 0.3));
    let inside = step(abs(f.x - 0.5), w * 0.5) * step(0.12, f.y) * step(f.y, 0.12 + ht);
    // The lit back of a shelf, brightest under the light at its top.
    var col = vec3f(1.0, 0.93, 0.9) * (0.55 + 0.45 * f.y);
    let label = vmLabel(h) * (0.75 + 0.5 * (1.0 - abs(f.x - 0.5) * 2.0));
    col = mix(col, label, inside);
    let shelf = 1.0 - step(0.1, f.y);
    col = mix(col, vec3f(0.1, 0.11, 0.13), shelf);
    // The frame around the window.
    let border = 1.0 - step(0.035, uv.x) * step(uv.x, 0.965) * step(0.03, uv.y) * step(uv.y, 0.97);
    col = mix(col, vec3f(0.02), border);
    let front = smoothstep(0.5, 0.9, n.z);
    ORI_ShadingInput.BaseColor = vec4f(col * 0.04, 1.0);
    ORI_ShadingInput.Roughness = 0.06;
    ORI_ShadingInput.Metallic = 0.0;
    ORI_ShadingInput.Specular = 1.0;
    ORI_ShadingInput.AmbientOcclusion = 1.0;
    ORI_ShadingInput.EmissiveColor = vec4f(col * materialUniform.glow * front * (1.0 - border), 1.0);
    ORI_ShadingInput.Normal = n;
    useShadow();
    BxDFShading();
}

// A framed black and white photograph of a city at night: towers with a
// few lit windows against a pale sky, on a white mat. center and size give
// the print in world space; seed picks another skyline.
// @property center vec4 0 0 0 0
// @property size vec4 0.5 0.7 0 0
// @property seed float 1 0 100

fn psHash(p: vec2f) -> f32 {
    var q = fract(p * vec2f(0.1031, 0.1030));
    q += dot(q, q.yx + 33.33);
    return fract((q.x + q.y) * q.x);
}

fn frag() {
    let p = ORI_VertexVarying.vWorldPos.xyz;
    let n = normalize(ORI_VertexVarying.vWorldNormal);
    let a = abs(n);
    let c0 = materialUniform.center.xyz;
    var q = vec2f(p.x - c0.x, p.y - c0.y);
    if (a.x > a.z) {
        q = vec2f(-(p.z - c0.z) * sign(n.x), p.y - c0.y);
    }
    let uv = q / max(materialUniform.size.xy, vec2f(0.01)) + 0.5;
    let seed = materialUniform.seed;
    // The sky, lighter low down where the city glows.
    var c = mix(0.78, 0.42, uv.y);
    // Towers in columns of their own height.
    let x = uv.x * 11.0;
    let id = floor(x);
    let top = 0.18 + 0.6 * psHash(vec2f(id, seed)) * psHash(vec2f(id * 3.1, seed + 1.0));
    let tower = step(uv.y, top);
    let wg = vec2f(fract(x) * 4.0, uv.y * 46.0);
    let lit = step(0.35, fract(wg.x)) * step(0.45, fract(wg.y)) * step(0.78, psHash(floor(wg) + vec2f(id * 13.0, seed)));
    c = mix(c, 0.1 + 0.75 * lit, tower);
    // The white mat around the print.
    let mount = 1.0 - step(0.06, uv.x) * step(uv.x, 0.94) * step(0.05, uv.y) * step(uv.y, 0.95);
    c = mix(c, 0.88, mount);
    ORI_ShadingInput.BaseColor = vec4f(vec3f(c), 1.0);
    ORI_ShadingInput.Roughness = 0.3;
    ORI_ShadingInput.Metallic = 0.0;
    ORI_ShadingInput.Specular = 0.5;
    ORI_ShadingInput.AmbientOcclusion = 1.0;
    ORI_ShadingInput.EmissiveColor = vec4f(0.0, 0.0, 0.0, 1.0);
    ORI_ShadingInput.Normal = n;
    useShadow();
    BxDFShading();
}

// A city building: its wall texture projected in world space (as
// Triplanar.wgsl) with a grid of windows on every wall above a height. A
// share of them is lit, warm or cold, behind curtains drawn by different
// amounts; the rest is dark glass. bay: meters between windows along a
// wall; floorHeight: between floors; above: where the first floor starts.
// @property albedo texture white
// @property normalTex texture normal
// @property armTex texture data
// @property tile float 2 0.05 50
// @property maps float 0 0 3
// @property bay float 2.6 0.5 10
// @property floorHeight float 3.2 1 10
// @property above float 7 0 100
// @property lit float 0.3 0 1
// @property glow float 1.4 0 8

struct BwSample {
    color: vec4f,
    arm: vec3f,
    bump: vec3f,
};

fn bwTriplanar(p: vec3f, n: vec3f) -> BwSample {
    let s = 1.0 / max(materialUniform.tile, 0.001);
    var w = pow(abs(n), vec3f(4.0));
    w = w / max(w.x + w.y + w.z, 0.0001);
    w = select(vec3f(0.0), w, w > vec3f(0.02));
    w = w / max(w.x + w.y + w.z, 0.0001);
    let dx = dpdx(p) * s;
    let dy = dpdy(p) * s;
    let flags = u32(materialUniform.maps + 0.5);
    let useNormal = (flags & 1u) != 0u;
    let useArm = (flags & 2u) != 0u;
    var o: BwSample;
    o.color = vec4f(0.0);
    o.arm = vec3f(0.0);
    o.bump = vec3f(0.0);
    if (w.x > 0.0) {
        let uv = vec2f(p.z, -p.y) * s;
        let gx = vec2f(dx.z, -dx.y);
        let gy = vec2f(dy.z, -dy.y);
        o.color += textureSampleGrad(albedo, albedoSampler, uv, gx, gy) * w.x;
        o.arm += select(vec3f(1.0), textureSampleGrad(armTex, armTexSampler, uv, gx, gy).rgb, useArm) * w.x;
        if (useNormal) {
            let t = textureSampleGrad(normalTex, normalTexSampler, uv, gx, gy).xy * 2.0 - 1.0;
            o.bump += (t.x * vec3f(0.0, 0.0, 1.0) + t.y * vec3f(0.0, 1.0, 0.0)) * w.x;
        }
    }
    if (w.y > 0.0) {
        let uv = vec2f(p.x, p.z) * s;
        let gx = vec2f(dx.x, dx.z);
        let gy = vec2f(dy.x, dy.z);
        o.color += textureSampleGrad(albedo, albedoSampler, uv, gx, gy) * w.y;
        o.arm += select(vec3f(1.0), textureSampleGrad(armTex, armTexSampler, uv, gx, gy).rgb, useArm) * w.y;
        if (useNormal) {
            let t = textureSampleGrad(normalTex, normalTexSampler, uv, gx, gy).xy * 2.0 - 1.0;
            o.bump += (t.x * vec3f(1.0, 0.0, 0.0) + t.y * vec3f(0.0, 0.0, -1.0)) * w.y;
        }
    }
    if (w.z > 0.0) {
        let uv = vec2f(p.x, -p.y) * s;
        let gx = vec2f(dx.x, -dx.y);
        let gy = vec2f(dy.x, -dy.y);
        o.color += textureSampleGrad(albedo, albedoSampler, uv, gx, gy) * w.z;
        o.arm += select(vec3f(1.0), textureSampleGrad(armTex, armTexSampler, uv, gx, gy).rgb, useArm) * w.z;
        if (useNormal) {
            let t = textureSampleGrad(normalTex, normalTexSampler, uv, gx, gy).xy * 2.0 - 1.0;
            o.bump += (t.x * vec3f(1.0, 0.0, 0.0) + t.y * vec3f(0.0, 1.0, 0.0)) * w.z;
        }
    }
    return o;
}

fn bwHash(p: vec2f) -> f32 {
    var q = fract(p * vec2f(0.1031, 0.1030));
    q += dot(q, q.yx + 33.33);
    return fract((q.x + q.y) * q.x);
}

fn frag() {
    let n0 = normalize(ORI_VertexVarying.vWorldNormal);
    let p = ORI_VertexVarying.vWorldPos.xyz;
    let t = bwTriplanar(p, n0);
    var c = t.color.rgb * materialUniform.baseColor.rgb;
    var rough = clamp(t.arm.g * materialUniform.roughness, 0.02, 1.0);
    var n = normalize(n0 + t.bump);
    var emit = vec3f(0.0);
    let a = abs(n0);
    let wall = 1.0 - step(0.3, a.y);
    let u = select(p.x, p.z, a.x > a.z);
    let g = vec2f(u / materialUniform.bay, (p.y - materialUniform.above) / materialUniform.floorHeight);
    let cell = floor(g);
    let f = g - cell;
    let inWin = step(0.28, f.x) * step(f.x, 0.72) * step(0.3, f.y) * step(f.y, 0.8) * step(0.0, g.y) * wall;
    // A thin stone sill under each window.
    let sill = step(0.24, f.x) * step(f.x, 0.76) * step(0.26, f.y) * step(f.y, 0.3) * step(0.0, g.y) * wall;
    c = mix(c, vec3f(0.32, 0.31, 0.3), sill);
    if (inWin > 0.5) {
        let side = vec2f(n0.x * 31.0 + n0.z * 7.0, n0.z * 17.0);
        let on = step(1.0 - materialUniform.lit, bwHash(cell + side));
        let warm = step(0.3, bwHash(cell + side + vec2f(5.1, 2.3)));
        let lampCol = mix(vec3f(0.6, 0.78, 1.0), vec3f(1.0, 0.68, 0.36), warm);
        // Curtains drawn by different amounts: the lit gap is brightest.
        let gap = 0.25 + 0.6 * bwHash(cell + side + vec2f(9.0, 4.0));
        let wx = (f.x - 0.28) / 0.44;
        let curtain = mix(0.35, 1.0, smoothstep(gap - 0.08, gap + 0.08, abs(wx - 0.5) * 2.0 + 0.5 - gap * 0.5));
        emit = lampCol * on * curtain * materialUniform.glow * (0.55 + 0.45 * bwHash(cell + side + vec2f(3.3, 8.8)));
        c = vec3f(0.015, 0.02, 0.03);
        rough = 0.06;
        n = n0;
        // Mullions: a frame round the glass and a cross of bars.
        let wy = (f.y - 0.3) / 0.5;
        let rim = 1.0 - step(0.04, wx) * step(wx, 0.96) * step(0.04, wy) * step(wy, 0.96);
        let bar = max(rim, max(step(abs(wx - 0.5), 0.025), step(abs(wy - 0.62), 0.03)));
        emit = emit * (1.0 - bar);
        c = mix(c, vec3f(0.09, 0.085, 0.08), bar);
        rough = mix(rough, 0.6, bar);
    }
    ORI_ShadingInput.BaseColor = vec4f(c, 1.0);
    ORI_ShadingInput.Roughness = rough;
    ORI_ShadingInput.Metallic = 0.0;
    ORI_ShadingInput.Specular = 1.0;
    ORI_ShadingInput.AmbientOcclusion = t.arm.r;
    ORI_ShadingInput.EmissiveColor = vec4f(emit + materialUniform.emissiveColor.rgb, 1.0);
    ORI_ShadingInput.Normal = n;
    useShadow();
    BxDFShading();
}
